#!/usr/bin/env bash
# GSZ step136 — admin "Deliver & notify customer": marking an order delivered now
# sets delivered_at, saves optional credentials/details, and messages the customer
# (WhatsApp + email) + owner, via new lib/deliver.js. Fixes invite/paid orders that
# sat on "Delivering" with the customer never told. Patches adminOrders.js +
# order_detail.ejs. No migration. Idempotent; restores on failure.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step136-$TS"; TMP=$(mktemp -d)
PATCHED=(routes/adminOrders.js views/admin/order_detail.ejs)
NEW=(lib/deliver.js)
echo "==> step136: deliver & notify from admin"
mkdir -p "$BK"; for f in "${PATCHED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"
restore(){
  echo "!! FAILED — restoring"
  for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  for f in "${NEW[@]}"; do keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done; if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi; done
  pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."
}
trap 'restore' ERR
echo "==> writing new files"; mkdir -p "$GSZ/lib"
echo "" | base64 -d > "$GSZ/lib/deliver.js"
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying patches"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/lib/deliver.js"; node --check "$GSZ/routes/adminOrders.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$GSZ/views/admin/order_detail.ejs','utf8'),{filename:'o'});console.log('    ejs ok')"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step136 OK ✅  On an order page, 'Deliver & notify customer' now delivers it, sends the WhatsApp + email (with any details you type), and alerts you. Use it for stuck vendor-invite orders."
